entries[304015] = { ["name"] = "Konflikt und Zwietracht", ["text"] = "Azerit Essenz\nSofort\n[\nHochexplosivfalle\n40 Meter Reichweite\nSofort 40 Sek. Abklingzeit Requires Hunter Schleudert eine Feuerfalle an den Zielort, die explodiert, wenn sich ein Gegner nähert. Verursacht (57.33% der Angriffskraft) Feuerschaden und stößt alle Gegner zurück. Maximal 1 Falle. Eine Falle bleibt 1 Min. lang bestehen. [ Bindende Fesseln : Von der Hochexplosivfalle zurückgestoßene Ziele fügen Euch danach 8 Sek. lang 10% weniger Schaden zu ] ] [\nHochexplosivfalle\n40 Meter Reichweite\nSofort 40 Sek. Abklingzeit Requires Hunter Schleudert eine Feuerfalle an den Zielort, die explodiert, wenn sich ein Gegner nähert. Verursacht (57.33% der Angriffskraft) Feuerschaden und stößt alle Gegner zurück. Maximal 1 Falle. Eine Falle bleibt 1 Min. lang bestehen. [ Bindende Fesseln : Von der Hochexplosivfalle zurückgestoßene Ziele fügen Euch danach 8 Sek. lang 10% weniger Schaden zu ] ] [\nHochexplosivfalle\n40 Meter Reichweite\nSofort 40 Sek. Abklingzeit Requires Hunter Schleudert eine Feuerfalle an den Zielort, die explodiert, wenn sich ein Gegner nähert. Verursacht (57.33% der Angriffskraft) Feuerschaden und stößt alle Gegner zurück. Maximal 1 Falle. Eine Falle bleibt 1 Min. lang bestehen. [ Bindende Fesseln : Von der Hochexplosivfalle zurückgestoßene Ziele fügen Euch danach 8 Sek. lang 10% weniger Schaden zu ] ]" }
